package com.heluo.museum.appointment;
import com.heluo.museum.common.api.ApiResponse;
import java.time.LocalDate;import java.util.List;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/appointment-slots") public class AppointmentSlotController {private final JdbcTemplate jdbc;AppointmentSlotController(JdbcTemplate jdbc){this.jdbc=jdbc;}@GetMapping public ApiResponse<List<Slot>> list(@RequestParam(required=false) LocalDate dateFrom,@RequestParam(required=false) LocalDate dateTo){LocalDate from=dateFrom==null?LocalDate.now():dateFrom;LocalDate to=dateTo==null?from.plusDays(14):dateTo;return ApiResponse.ok(jdbc.query("select id,visit_date,start_time,end_time,capacity,reserved_people from appointment_slots where visit_date between ? and ? and status='OPEN' and reserved_people<capacity order by visit_date,start_time",(r,n)->new Slot(r.getLong(1),r.getDate(2).toLocalDate(),r.getTime(3).toLocalTime(),r.getTime(4).toLocalTime(),r.getInt(5)-r.getInt(6)),from,to),"slots");}public record Slot(long id,LocalDate visitDate,java.time.LocalTime startTime,java.time.LocalTime endTime,int remainingPeople){}}
